body {
  display: grid;
  place-items: center;
  box-sizing: border-box;
  min-block-size: 100dvb;
  margin: 0;
  padding: 20px;
  font-family: 'PT Sans', sans-serif;
  background-color: skyblue;
  background-image:
    image-set(
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.avif) type("image/avif") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.webp) type("image/webp") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.png) type("image/png") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-2x.avif) type("image/avif") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-2x.webp) type("image/webp") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-2x.png) type("image/png") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-3x.avif) type("image/avif") 3x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-3x.webp) type("image/webp") 3x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/fish-3x.png) type("image/png") 3x
    ),
    image-set(
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.avif) type("image/avif") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.webp) type("image/webp") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.jpg) type("image/jpeg") 1x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-2x.avif) type("image/avif") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-2x.webp) type("image/webp") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-2x.jpg) type("image/jpeg") 2x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-3x.avif) type("image/avif") 3x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-3x.webp) type("image/webp") 3x,
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/step2/water-3x.jpg) type("image/jpeg") 3x
    );
  background-repeat: no-repeat;
  background-position: 10% 90%, center;
  background-size: 200px, cover;
}

h1 {
  margin: 0;
  padding: 10px;
  font-weight: normal;
  font-size: 60px;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
  background-color: #fff;
}
